/* ---------- Cards ---------- */
[
  [C8, 'Ch. 8', 'Infectious vs communicable', 'INFECTIOUS = caused by a biological agent (virus, bacterium, parasite). COMMUNICABLE = an infectious disease that can spread to a person, directly or indirectly.', 'All communicable diseases are infectious; not all infectious diseases are communicable.'],
  [C8, 'Ch. 8', 'Who is at risk', '"Young, old, weak, wild, wandering, working": young children · older adults · weak (suppressed) immunity · wild (high-risk) lifestyle · wandering (international travelers) · working in health care.', ''],
  [C8, 'Ch. 8', 'Immunity', '"Active you build, it lasts and lasts; passive you borrow, it fades fast." Active = long term. Passive = short term. Both can be natural or acquired.', 'Primary vaccine failure = the vaccine fails. Secondary = the immune response fails. Hesitancy = delay or refusal.'],
  [C8, 'Ch. 8', 'Most reported vs most common', 'Chlamydia = most frequently REPORTED infectious disease in the US. HPV = most COMMON STI.', 'Chlamydia in women: infertility, PID, ectopic, chronic pain. Treat with antibiotics plus all partners.'],
  [C8, 'Ch. 8', 'TB', 'Spreads by droplet. Common in HIV-infected, poor, crowded enclosed urban areas. Signs: cough >3 weeks, blood or phlegm, night sweats, weight loss, fever. Drugs = "RIPE": Rifampin, Isoniazid, Pyrazinamide, Ethambutol.', 'DOT (directly observed therapy) = tertiary.'],
  [C8, 'Ch. 8', 'STI quick facts', 'HPV: 40+ genital types; subtypes like 16 and 18 cause >90% of cervical cancers; condoms ~50%. Gonorrhea and chlamydia: treat ALL partners from the last 60 days (none? treat the last contact). Syphilis: primary = single chancre.', ''],
  [C8, 'Ch. 8', 'Investigating a reportable disease', 'Review the info → suspect or lab-confirmed? → case definition → disease info → disease-specific questionnaire.', ''],
  [C8, 'Ch. 8', 'C. diff hand hygiene', '"Spores laugh at alcohol." After C. difficile: soap and water.', ''],
  [ACT, 'Prevention', 'Communicable disease: three levels', 'PRIMARY = teach and vaccinate (immunizations, travel counseling, hand hygiene, condoms, safe sex). SECONDARY = find it or catch it right after exposure (screening, case finding, contact tracing, PEP, referral for diagnosis, quarantine). TERTIARY = already sick (treatment, rehab, DOT, medication adherence, community resources, isolation).', 'From the professor\'s answer key.'],
  [ACT, 'Prevention', 'Quarantine vs isolation', '"Quarantine the questionable; isolate the ill." Quarantine (the exposed) = secondary. Isolation (the sick) = tertiary.', ''],
  [ACT, 'Prevention', 'PEP is secondary', 'Post-exposure prophylaxis (hepatitis A, rabies): the exposure already happened, so it is early action = SECONDARY, not primary.', ''],
  [ACT, 'Core functions', 'Core functions vs communicable disease', 'Identify cases = Assessment. Program to spray insecticide = Policy development. Make sure TB skin tests get follow-up = Assurance.', ''],
  [C9, 'Ch. 9', 'Four hazard types', '"CBPP": Chemical (exhaust, pesticides) · Biological (water, air, food, vectors) · Physical (unsafe equipment, noise, radiation) · Psychosocial (natural disasters).', ''],
  [C9, 'Ch. 9', 'Precautionary principle', '"Better safe than sorry · Look before you leap · First, do no harm." No clear safety data? Do not use it.', ''],
  [C9, 'Ch. 9', 'Home hazards', 'Poisonings = most accidental deaths (young kids). Falls = older adults. Burns = smoke detectors help. Drowning = children. Firearms = often while cleaning. Radon = colorless, odorless, from uranium. CO = byproduct of combustion. Tobacco smoke = major indoor air pollutant.', ''],
  [C9, 'Ch. 9', 'Air Quality Index', 'Green 0–50 Good · Yellow 51–100 Moderate · Orange 101–150 Sensitive groups · Red 151–200 Unhealthy · Purple 201–300 Very unhealthy · Maroon 301–500 Hazardous.', '"Get Your Old Raincoat, Pollution\'s Mean." Steps of 50 up to 200, then 300, then 500.'],
  [C9, 'Ch. 9', 'Environmental prevention', 'PRIMARY: educate, advocate for safe air and water, recycling. SECONDARY: environmental health histories, monitor workers, screen kids 6 months–5 years for lead, assess neighborhoods. TERTIARY: refer for lead abatement, teach asthma triggers, support toxic site cleanup.', ''],
  [C9, 'Ch. 9', 'Core functions in environmental health', 'Assessment = monitor and investigate hazards. Policy development = inform, educate, mobilize partnerships, make policies. Assurance = enforce laws and regulations (and make sure services happen, e.g., USDA school lunch standards).', ''],
  [C11, 'Ch. 11', 'Two types of change', '"Evolution is slow; revolution is overnight." Evolutionary = gradual, modifies (cutting back cigarettes). Revolutionary = rapid, drastic, threatening (sudden job loss, quitting overnight).', ''],
  [C11, 'Ch. 11', 'Three stages of change', 'Unfreeze → Change (move) → Refreeze. Like reshaping an ice cube: melt it, reshape it, set it.', 'Participatory action research: the goal is social change.'],
  [C11, 'Ch. 11', 'Transtheoretical Model', 'Not ready yet → Thinking about it → Preparing for action → Taking action → Maintaining. Sliding backward is not unusual.', 'Relapse is part of the cycle, so be encouraging.'],
  [C11, 'Ch. 11', 'Health Belief Model: six concepts', '"Sam Says Better Bring Coffee, Sweetie": Susceptibility · Seriousness · Benefits · Barriers · Cues to action · Self-efficacy.', 'Benefits vs barriers is the core trade-off.'],
  [C11, 'Ch. 11', 'Health Promotion Model', 'Three areas: individual characteristics and experiences → behavior-specific cognitions and affect → behavioral outcomes.', ''],
  [C11, 'Ch. 11', 'Health literacy', 'Obtain, process and understand health information to make decisions. Low health literacy: trouble with forms, medication directions, chronic disease, preventive care, finding providers.', 'Teach-back, clear language, essentials only, space it out.'],
  [C14, 'Ch. 14', 'Five family health practice guidelines', 'Work with the family collectively · START WHERE THE FAMILY IS · Adapt to their stage of development · Recognize structural variations · EMPOWER: emphasize strengths.', ''],
  [C14, 'Ch. 14', 'Home visit guidelines', 'Engage to build trust → observe (trust your feelings) → focus on issues and move toward goals → review and praise strengths → plan the next visit. Length: >20 but <60 minutes.', 'You are a guest; the family are the experts. Set the visit time WITH them.'],
  [C14, 'Ch. 14', 'Five family assessment guidelines', 'Total unit · Goal-directed questions · Data over time · Quantitative + qualitative · Professional judgment.', ''],
  [C14, 'Ch. 14', 'Genogram vs ecomap', 'GENO-gram = GENerations (the family tree). ECO-map = the family\'s ECOsystem: links to community groups, schools, faith communities.', '"Is your family involved in community organizations?" → ecomap.'],
  [C14, 'Ch. 14', 'Three evaluations', 'Structure–process (organization, timing, environment, distractions) · Outcome (did the family\'s health change?) · Self (my preparation, strengths, weaknesses).', ''],
  [C14, 'Ch. 14', 'Family life cycle', 'Partnership → childbearing → preschool → school-age → teenage → launching → middle-aged parents → aging.', 'Developmental tasks are crucial to moving through the cycle.'],
  [C18, 'Ch. 18', 'Three types of crisis', 'Developmental = expected life stage. Situational = unexpected upset (job loss). Traumatic = unexpected, overwhelming, unusual (disaster, attack).', 'A crisis can come from an internal OR external force.'],
  [C18, 'Ch. 18', 'Violence prevention levels', 'PRIMARY: parenting classes, communication, self-esteem, problem-solving, dating violence education. SECONDARY: rapport, assess lethality, action plan, report abuse. TERTIARY: rehab, support groups, sexual assault referrals, forensic exam.', 'Problem-solving teaching = primary, not secondary.'],
  [C18, 'Ch. 18', 'Abusive head trauma', '"Eyes and brain, little else": bilateral retinal hemorrhages, subdural or subarachnoid bleeding, often no other external signs. Bruises and fractures point to physical abuse instead.', ''],
  [C18, 'Ch. 18', 'Cycle of violence', '"Tense, explode, hearts and flowers, deny": Tension-building → Acute explosion → Honeymoon → Denial.', 'IPV = abuse in close relationships, current or previous; leading cause of morbidity and mortality in women worldwide.'],
  [C18, 'Ch. 18', 'Crisis intervention', 'Show acceptance, confront the crisis, find facts, let feelings out, NO false reassurance, NO blame, find coping mechanisms, encourage accepting help.', ''],
  [EA, 'Elder abuse', 'Five types of elder abuse', '"SPEND": Sexual · Physical · Emotional · Neglect · Dollars (financial).', 'Age 60+. Abuser is a caregiver or trusted person.'],
  [EA, 'Elder abuse', 'Elder abuse numbers', 'About 1 in 10 people 60+ living at home. Men have higher rates of assault and homicide than women. Underreported.', ''],
  [EA, 'Elder abuse', 'Report and prevent', 'Report to adult protective services, the long-term care ombudsman, or the police. Prevent: listen, check in on isolated elders, support overburdened caregivers, know abuse signs vs normal aging.', '']
].forEach(([source, cat, front, back, tip]) => window.RHYMES.push({ course: C, cat, front, back, tip, source }));
